TITLE = "มหานามสูตร (อนุสติ ๖ ในทุกอิริยาบถ)"
SUB = "อังคุตตรนิกาย เอกาทสกนิบาต (AN 11.12) · ระลึกถึงคุณ ๖ ในทุกอิริยาบถ"
EXPAND = {
    "an11.12:4.2": "‘itipi so bhagavā arahaṁ sammāsambuddho vijjācaraṇasampanno sugato lokavidū anuttaro purisadammasārathi satthā devamanussānaṁ buddho bhagavā’ti.",
    "an11.12:5.1": "Puna caparaṁ tvaṁ, mahānāma, dhammaṁ anussareyyāsi: " + "‘svākkhāto bhagavatā dhammo sandiṭṭhiko akāliko ehipassiko opaneyyiko paccattaṁ veditabbo viññūhī’ti." + " " + "Yasmiṁ, mahānāma, samaye ariyasāvako dhammaṁ anussarati, nevassa tasmiṁ samaye rāgapariyuṭṭhitaṁ cittaṁ hoti, na dosapariyuṭṭhitaṁ cittaṁ hoti, na mohapariyuṭṭhitaṁ cittaṁ hoti; ujugatamevassa tasmiṁ samaye cittaṁ hoti dhammaṁ ārabbha. Ujugatacitto kho pana, mahānāma, ariyasāvako labhati atthavedaṁ, labhati dhammavedaṁ, labhati dhammūpasaṁhitaṁ pāmojjaṁ. Pamuditassa pīti jāyati, pītimanassa kāyo passambhati, passaddhakāyo sukhaṁ vediyati, sukhino cittaṁ samādhiyati." + " " + "Imaṁ kho tvaṁ, mahānāma, dhammānussatiṁ gacchantopi bhāveyyāsi, ṭhitopi bhāveyyāsi, nisinnopi bhāveyyāsi, sayānopi bhāveyyāsi, kammantaṁ adhiṭṭhahantopi bhāveyyāsi, puttasambādhasayanaṁ ajjhāvasantopi bhāveyyāsi.",
    "an11.12:5.2": "Puna caparaṁ tvaṁ, mahānāma, saṅghaṁ anussareyyāsi: " + "‘suppaṭipanno bhagavato sāvakasaṅgho, ujuppaṭipanno bhagavato sāvakasaṅgho, ñāyappaṭipanno bhagavato sāvakasaṅgho, sāmīcippaṭipanno bhagavato sāvakasaṅgho, yadidaṁ cattāri purisayugāni aṭṭha purisapuggalā esa bhagavato sāvakasaṅgho āhuneyyo pāhuneyyo dakkhiṇeyyo añjalikaraṇīyo anuttaraṁ puññakkhettaṁ lokassā’ti." + " " + "Yasmiṁ, mahānāma, samaye ariyasāvako saṅghaṁ anussarati, nevassa tasmiṁ samaye rāgapariyuṭṭhitaṁ cittaṁ hoti, na dosapariyuṭṭhitaṁ cittaṁ hoti, na mohapariyuṭṭhitaṁ cittaṁ hoti; ujugatamevassa tasmiṁ samaye cittaṁ hoti saṅghaṁ ārabbha. Ujugatacitto kho pana, mahānāma, ariyasāvako labhati atthavedaṁ, labhati dhammavedaṁ, labhati dhammūpasaṁhitaṁ pāmojjaṁ. Pamuditassa pīti jāyati, pītimanassa kāyo passambhati, passaddhakāyo sukhaṁ vediyati, sukhino cittaṁ samādhiyati." + " " + "Imaṁ kho tvaṁ, mahānāma, saṅghānussatiṁ gacchantopi bhāveyyāsi, ṭhitopi bhāveyyāsi, nisinnopi bhāveyyāsi, sayānopi bhāveyyāsi, kammantaṁ adhiṭṭhahantopi bhāveyyāsi, puttasambādhasayanaṁ ajjhāvasantopi bhāveyyāsi.",
    "an11.12:5.3": "Puna caparaṁ tvaṁ, mahānāma, " + "attano sīlaṁ anussareyyāsi akhaṇḍaṁ acchiddaṁ asabalaṁ akammāsaṁ bhujissaṁ viññuppasatthaṁ aparāmaṭṭhaṁ samādhisaṁvattanikaṁ." + " " + "Yasmiṁ, mahānāma, samaye ariyasāvako sīlaṁ anussarati, nevassa tasmiṁ samaye rāgapariyuṭṭhitaṁ cittaṁ hoti, na dosapariyuṭṭhitaṁ cittaṁ hoti, na mohapariyuṭṭhitaṁ cittaṁ hoti; ujugatamevassa tasmiṁ samaye cittaṁ hoti sīlaṁ ārabbha. Ujugatacitto kho pana, mahānāma, ariyasāvako labhati atthavedaṁ, labhati dhammavedaṁ, labhati dhammūpasaṁhitaṁ pāmojjaṁ. Pamuditassa pīti jāyati, pītimanassa kāyo passambhati, passaddhakāyo sukhaṁ vediyati, sukhino cittaṁ samādhiyati." + " " + "Imaṁ kho tvaṁ, mahānāma, sīlānussatiṁ gacchantopi bhāveyyāsi, ṭhitopi bhāveyyāsi, nisinnopi bhāveyyāsi, sayānopi bhāveyyāsi, kammantaṁ adhiṭṭhahantopi bhāveyyāsi, puttasambādhasayanaṁ ajjhāvasantopi bhāveyyāsi.",
    "an11.12:5.4": "Puna caparaṁ tvaṁ, mahānāma, " + "attano cāgaṁ anussareyyāsi: ‘lābhā vata me, suladdhaṁ vata me, yohaṁ maccheramalapariyuṭṭhitāya pajāya vigatamalamaccherena cetasā agāraṁ ajjhāvasāmi muttacāgo payatapāṇī vossaggarato yācayogo dānasaṁvibhāgarato’ti." + " " + "Yasmiṁ, mahānāma, samaye ariyasāvako cāgaṁ anussarati, nevassa tasmiṁ samaye rāgapariyuṭṭhitaṁ cittaṁ hoti, na dosapariyuṭṭhitaṁ cittaṁ hoti, na mohapariyuṭṭhitaṁ cittaṁ hoti; ujugatamevassa tasmiṁ samaye cittaṁ hoti cāgaṁ ārabbha. Ujugatacitto kho pana, mahānāma, ariyasāvako labhati atthavedaṁ, labhati dhammavedaṁ, labhati dhammūpasaṁhitaṁ pāmojjaṁ. Pamuditassa pīti jāyati, pītimanassa kāyo passambhati, passaddhakāyo sukhaṁ vediyati, sukhino cittaṁ samādhiyati." + " " + "Imaṁ kho tvaṁ, mahānāma, cāgānussatiṁ gacchantopi bhāveyyāsi, ṭhitopi bhāveyyāsi, nisinnopi bhāveyyāsi, sayānopi bhāveyyāsi, kammantaṁ adhiṭṭhahantopi bhāveyyāsi, puttasambādhasayanaṁ ajjhāvasantopi bhāveyyāsi.",
    "an11.12:5.6": "devatā anussareyyāsi: ‘santi devā cātumahārājikā, santi devā tāvatiṁsā, santi devā yāmā, santi devā tusitā, santi devā nimmānaratino, santi devā paranimmitavasavattino, santi devā brahmakāyikā, santi devā tatuttari.’",
    "an11.12:5.8": "Yathārūpena sīlena samannāgatā tā devatā ito cutā tatthūpapannā, mayhampi tathārūpaṁ sīlaṁ saṁvijjati.",
    "an11.12:5.9": "Yathārūpena sutena samannāgatā tā devatā ito cutā tatthūpapannā, mayhampi tathārūpaṁ sutaṁ saṁvijjati.",
    "an11.12:5.10": "Yathārūpena cāgena samannāgatā tā devatā ito cutā tatthūpapannā, mayhampi tathārūpo cāgo saṁvijjati.",
}
TH = {
    "1": "สมัยหนึ่ง พระผู้มีพระภาคเจ้าประทับอยู่ที่นิโครธาราม ใกล้กรุงกบิลพัสดุ์ แคว้นสักกะ ครั้งนั้น เจ้ามหานามะศากยะหายจากโรคได้ไม่นาน ภิกษุหลายรูปกำลังทำจีวรให้พระผู้มีพระภาคเจ้า ด้วยคิดว่า พระผู้มีพระภาคเจ้าทรงทำจีวรเสร็จแล้วจะเสด็จเที่ยวจาริกเมื่อล่วงสามเดือนไป",
    "2": "เจ้ามหานามะทราบข่าวว่า ภิกษุหลายรูปกำลังทำจีวรให้พระผู้มีพระภาคเจ้า พระองค์จะเสด็จจาริกเมื่อล่วงสามเดือน จึงเข้าเฝ้าพระผู้มีพระภาคเจ้า กราบแล้วนั่งลง ณ ที่สมควร ทูลถามว่า ข้าแต่พระองค์ผู้เจริญ ข้าพระองค์ได้ฟังมาว่าพระองค์จะเสด็จจาริก เมื่อพวกข้าพระองค์อยู่ด้วยธรรมเครื่องอยู่อย่างต่าง ๆ กัน ควรอยู่ด้วยธรรมเครื่องอยู่อย่างไหน",
    "3": "ดีแล้ว ๆ มหานามะ การที่พวกท่านเข้ามาถามอย่างนี้ สมควรแก่กุลบุตรทั้งหลาย มหานามะ ผู้มีศรัทธาจึงชื่อว่าถึงพร้อม ผู้ไม่มีศรัทธาไม่ชื่อว่าถึงพร้อม ผู้ปรารภความเพียรจึงชื่อว่าถึงพร้อม ผู้เกียจคร้านไม่ชื่อว่าถึงพร้อม ผู้มีสติตั้งมั่นจึงชื่อว่าถึงพร้อม ผู้หลงลืมสติไม่ชื่อว่าถึงพร้อม ผู้มีใจตั้งมั่นจึงชื่อว่าถึงพร้อม ผู้ไม่มีใจตั้งมั่นไม่ชื่อว่าถึงพร้อม ผู้มีปัญญาจึงชื่อว่าถึงพร้อม ผู้ไม่มีปัญญาไม่ชื่อว่าถึงพร้อม เธอตั้งอยู่ในธรรม ๕ ประการนี้แล้ว ควรเจริญธรรม ๖ ประการให้ยิ่งขึ้นไป",
    "4": "มหานามะ เธอควรระลึกถึงพระตถาคตว่า พระผู้มีพระภาคเจ้านั้น เป็นพระอรหันต์ ไกลจากกิเลส ตรัสรู้ชอบได้เอง ถึงพร้อมด้วยความรู้และความประพฤติ ไปดีแล้ว รู้แจ้งโลก เป็นผู้ฝึกคนที่ควรฝึกได้อย่างไม่มีใครยิ่งกว่า เป็นครูของเทวดาและมนุษย์ เป็นผู้รู้ ผู้ตื่น ผู้เบิกบาน เป็นผู้มีโชค ควรแก่การจำแนกธรรม ในเวลาใด อริยสาวกระลึกถึงพระตถาคต ในเวลานั้น ใจของเธอไม่ถูกราคะ โทสะ โมหะครอบงำ ใจตรงแน่วต่อพระตถาคต ผู้มีใจตรงแน่วย่อมได้ความรู้แจ้งในอรรถ ในธรรม ได้ความปราโมทย์ที่ประกอบด้วยธรรม ผู้มีปราโมทย์ย่อมเกิดปีติ ผู้มีใจปีติกายย่อมสงบ ผู้มีกายสงบย่อมได้สุข ผู้มีสุขใจย่อมตั้งมั่น มหานามะ เธอควรเจริญพุทธานุสสตินี้ ทั้งเวลาเดิน เวลายืน เวลานั่ง เวลานอน เวลาทำการงาน และแม้เวลาอยู่บนที่นอนที่มีลูก ๆ นอนเบียดอยู่",
    "5": "อีกข้อหนึ่ง เธอควรระลึกถึงพระธรรม ระลึกถึงพระสงฆ์ ระลึกถึงศีลของตน ระลึกถึงการให้ของตน และระลึกถึงเทวดาว่า เทวดาชั้นจาตุมหาราชิกามีอยู่ ชั้นดาวดึงส์มีอยู่ ชั้นยามามีอยู่ ชั้นดุสิตมีอยู่ ชั้นนิมมานรดีมีอยู่ ชั้นปรนิมมิตวสวัตดีมีอยู่ ชั้นพรหมกายิกามีอยู่ ชั้นที่สูงกว่านั้นก็มีอยู่ เทวดาเหล่านั้นมีศรัทธา ศีล สุตะ จาคะ ปัญญาแบบใด จึงจุติจากโลกนี้ไปเกิดที่นั่น เราก็มีแบบนั้น ในเวลาใด อริยสาวกระลึกถึงศรัทธา ศีล สุตะ จาคะ ปัญญา ทั้งของตนและของเทวดาเหล่านั้น ใจตรงแน่วต่อเทวดาเหล่านั้น ผู้มีใจตรงแน่วย่อมได้ความรู้แจ้ง ได้ความปราโมทย์ เกิดปีติ กายสงบ ได้สุข ใจตั้งมั่น มหานามะ เธอควรเจริญเทวตานุสสตินี้ ทั้งเวลาเดิน ยืน นั่ง นอน เวลาทำการงาน และแม้เวลาอยู่บนที่นอนที่มีลูก ๆ นอนเบียดอยู่ (จบสูตรที่ ๒)",
}
